cat > /tmp/init.sql <<'EOF'
INSTALL spatial; LOAD spatial;
INSTALL httpfs; LOAD httpfs;
SET http_timeout=120000;
EOF
echo "===== FIELDS SCHEMA =====" 
duckdb -init /tmp/init.sql -c "DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet') LIMIT 1;" 2>/dev/null

cat > /tmp/init.sql <<'EOF'
INSTALL spatial; LOAD spatial;
INSTALL httpfs; LOAD httpfs;
SET http_timeout=300000;
SET geometry_always_xy=true;
EOF
cd /workspace
time duckdb -init /tmp/init.sql work.db -csv -c "
CREATE OR REPLACE TABLE list AS
  SELECT * FROM read_csv('lists/goias-sample.csv', header=true, all_varchar=true);
SELECT count(*) n_rows, count(DISTINCT cod_imovel) n_ids FROM list;
SELECT * FROM list LIMIT 2;
" 2>/dev/null

cd /workspace
time duckdb -init /tmp/init.sql work.db -csv -c "
CREATE OR REPLACE TABLE env AS SELECT ST_Extent(ST_Union_Agg(geometry)) AS e FROM car_listed;
CREATE OR REPLACE TABLE fields_env AS
  SELECT f.* FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet') f, env
  WHERE ST_Intersects(f.geometry, env.e);
SELECT count(*) n_fields_in_envelope FROM fields_env;
" 2>/dev/null

